CREATE TABLE operational_event(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,at_ms BIGINT NOT NULL,category VARCHAR(40) NOT NULL,aggregate_id VARCHAR(64) NOT NULL,code VARCHAR(64) NOT NULL);
CREATE INDEX ix_event_time ON operational_event(at_ms,seq);
CREATE TABLE operation_control(id INT PRIMARY KEY,revision BIGINT NOT NULL,accept_new BOOLEAN NOT NULL,pull_enabled BOOLEAN NOT NULL,contingency VARCHAR(20) NOT NULL);
INSERT INTO operation_control VALUES(1,0,FALSE,FALSE,'SOLO_CONSULTA');
CREATE TABLE external_operation(id VARCHAR(36) PRIMARY KEY,kind VARCHAR(32) NOT NULL,state VARCHAR(32) NOT NULL,provider_ref VARCHAR(120),last_code VARCHAR(40) NOT NULL,updated_ms BIGINT NOT NULL,revision BIGINT NOT NULL);
CREATE INDEX ix_external_state ON external_operation(state,updated_ms,id);
CREATE TABLE institutional_inbox(source VARCHAR(32) NOT NULL,id VARCHAR(36) NOT NULL,content_hash CHAR(64) NOT NULL,body TEXT NOT NULL,receipt TEXT NOT NULL,ack_pending BOOLEAN NOT NULL,created_ms BIGINT NOT NULL,PRIMARY KEY(source,id));
CREATE INDEX ix_inbox_ack ON institutional_inbox(ack_pending,created_ms,id);
